/**
 * Receipt breakdown and money-saving tips for one scanned receipt, using the person's own past receipts.
 * Every number is computed here; nothing is generated by a model.
 */
import { formatDate } from "./dates";
import { ECON_FACTS } from "./econ";
import { normalizeItemName } from "./inflation";
import type { Insight } from "./insights";
import { classifyItem, GROUP_LABEL, type ItemGroup } from "./itemGroups";
import { formatPct, formatPeso } from "./money";
import type { ReceiptCheck } from "./receipt";
import type { Centavos, Receipt, ReceiptItem } from "./types";

export interface GroupTotal {
  group: ItemGroup;
  label: string;
  centavos: Centavos;
  /** Share of the gross (pre-discount) spend, 0..1 */
  share: number;
  items: ReceiptItem[];
}

export function breakdownReceipt(items: ReceiptItem[]): GroupTotal[] {
  const map = new Map<ItemGroup, ReceiptItem[]>();
  for (const it of items) {
    const g = classifyItem(it.name, it.lineTotalCentavos);
    map.set(g, [...(map.get(g) ?? []), it]);
  }
  const gross = items.filter((i) => i.lineTotalCentavos > 0).reduce((s, i) => s + i.lineTotalCentavos, 0);
  return [...map.entries()]
    .map(([group, its]) => {
      const centavos = its.reduce((s, i) => s + i.lineTotalCentavos, 0);
      return { group, label: GROUP_LABEL[group], centavos, share: gross > 0 && centavos > 0 ? centavos / gross : 0, items: its };
    })
    .sort((a, b) => b.centavos - a.centavos);
}

const unitPrice = (i: ReceiptItem) => i.lineTotalCentavos / i.quantity;
const MIN_CHANGE = 0.03;

export interface ScanForTips {
  merchant: string;
  date: string;
  items: ReceiptItem[];
  totalCentavos: Centavos;
  vatCentavos: Centavos | null;
  check: ReceiptCheck;
  totalFound: boolean;
}

export function receiptTips(scan: ScanForTips, history: Receipt[]): Insight[] {
  const tips: Insight[] = [];

  if (scan.check.status === "mismatch") {
    tips.push({
      id: "mismatch",
      severity: "warning",
      title: "Hindi tugma ang items at TOTAL",
      body: `Ang nabasang items ay ${formatPeso(scan.check.itemsSumCentavos)} pero ang TOTAL ay ${formatPeso(scan.check.totalCentavos)}. I-check ang mga item bago i-save.`,
    });
  } else if (!scan.totalFound) {
    tips.push({ id: "no-total", severity: "warning", title: "Walang nabasang TOTAL", body: "Ginamit ang kabuuan ng mga item. Siguraduhing kita ang TOTAL sa litrato para ma-check ito." });
  }

  const discount = scan.items.filter((i) => i.lineTotalCentavos < 0).reduce((s, i) => s + i.lineTotalCentavos, 0);
  if (discount < 0) {
    tips.push({ id: "discount", severity: "good", title: "May discount ka", body: `Nakatipid ka ng ${formatPeso(-discount)} sa discount sa resibong ito.` });
  }

  // Compare each item with the person's own earlier purchases.
  const past = history.filter((r) => r.date <= scan.date);
  const changes: { name: string; prev: number; now: number; prevDate: string; change: number }[] = [];
  const cheaper: { name: string; here: number; there: number; where: string; saving: number }[] = [];
  for (const it of scan.items) {
    if (it.lineTotalCentavos <= 0) continue;
    const key = normalizeItemName(it.name);
    const now = unitPrice(it);
    const matches = past.flatMap((r) => r.items.filter((p) => normalizeItemName(p.name) === key && p.lineTotalCentavos > 0).map((p) => ({ r, p })));
    if (matches.length === 0) continue;
    const latest = matches.reduce((a, b) => (b.r.date > a.r.date ? b : a));
    const prev = unitPrice(latest.p);
    const change = now / prev - 1;
    if (Math.abs(change) >= MIN_CHANGE) changes.push({ name: it.name, prev, now, prevDate: latest.r.date, change });
    const otherStores = matches.filter((m) => m.r.merchant !== scan.merchant);
    if (otherStores.length) {
      const best = otherStores.reduce((a, b) => (unitPrice(b.p) < unitPrice(a.p) ? b : a));
      const there = unitPrice(best.p);
      if (there < now * (1 - MIN_CHANGE)) cheaper.push({ name: it.name, here: now, there, where: best.r.merchant, saving: Math.round((now - there) * it.quantity) });
    }
  }

  for (const c of cheaper.sort((a, b) => b.saving - a.saving).slice(0, 2)) {
    tips.push({
      id: `cheaper-${c.name}`,
      severity: "info",
      title: `Mas mura sa ${c.where}`,
      body: `${c.name}: ${formatPeso(Math.round(c.there))} sa ${c.where} vs ${formatPeso(Math.round(c.here))} dito (base sa mga resibo mo). Matitipid mo ang ${formatPeso(c.saving)} sa ganitong dami.`,
    });
  }
  for (const c of changes.sort((a, b) => Math.abs(b.change) - Math.abs(a.change)).slice(0, 2)) {
    const up = c.change > 0;
    tips.push({
      id: `price-${c.name}`,
      severity: up ? "info" : "good",
      title: `${up ? "Tumaas" : "Bumaba"} ang presyo: ${c.name}`,
      body: `${formatPeso(Math.round(c.prev))} noong ${formatDate(c.prevDate)} → ${formatPeso(Math.round(c.now))} ngayon (${up ? "+" : ""}${formatPct(c.change)}).`,
    });
  }

  const groups = breakdownReceipt(scan.items);
  const rice = groups.find((g) => g.group === "rice");
  if (rice) {
    tips.push({
      id: "rice",
      severity: "info",
      title: `Bigas: ${formatPct(rice.share)} ng resibo`,
      body: `Ang rice inflation ay ${ECON_FACTS.riceInflation.value}% (PSA, ${ECON_FACTS.riceInflation.period}). Ikumpara ang presyo kada kilo sa ibang tindahan bago bumili ng susunod na sako.`,
    });
  }

  if (scan.vatCentavos !== null && scan.vatCentavos > 0) {
    tips.push({ id: "vat", severity: "info", title: "VAT sa resibong ito", body: `Kasama na sa ${formatPeso(scan.totalCentavos)} ang ${formatPeso(scan.vatCentavos)} na 12% VAT.` });
  }

  return tips;
}
